PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (MAX(?values) as ?max_value) WHERE { ?off_attr <http://www.w3.org/2000/01/rdf-schema#subPropertyOf> :offValues; <http://www.w3.org/2000/01/rdf-schema#range> ?data_type. FILTER(?data_type != xsd:boolean) ?creatures ?off_attr ?values }

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (if ((?n_greater/?n_base_attr) > 0.5, 'True', 'False') as ?res) WHERE {  {SELECT (COUNT(?comp) as ?n_greater)   WHERE { ?base_attr rdfs:subPropertyOf :base. :Abaia ?base_attr ?ab_attr. :Vampire ?base_attr ?vamp_attr. BIND(if ((?ab_attr > ?vamp_attr), 1, 0) as ?comp) FILTER (?comp = 1)}} {SELECT (COUNT(?base_attr) as ?n_base_attr)  WHERE{?base_attr <http://www.w3.org/2000/01/rdf-schema#subPropertyOf> :base.}} }

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {  ?creatures :hasAlignment :TrueNeutral; :hasFortValue ?FortValue FILTER (?FortValue = '6'^^xsd:integer)}
